text:
{
  "rules": [
    {
      "category": "just_cause_eviction",
      "title": "Just Cause Eviction Protections",
      "requirement": "Landlords may only terminate a tenancy after 30 days of continuous and lawful occupancy for specified at-fault or no-fault just cause reasons stated in a written notice. For no-fault terminations, landlords must provide relocation assistance or a rent waiver equal to 3 months of rent.",
      "requirement_es": "Los propietarios solo pueden terminar un arrendamiento después de 30 días de ocupación continua y legal por razones específicas de causa justa con culpa o sin culpa indicadas en un aviso por escrito. Para terminaciones sin culpa, los propietarios deben proporcionar asistencia para la reubicación o una exención de alquiler equivalente a 3 meses de alquiler.",
      "key_value": {
        "label": "relocation assistance or rent waiver",
        "value": "3 months of rent"
      },
      "coverage_conditions": {
        "type": "AND",
        "clauses": [
          {
            "field": "tenancy_length_months",
            "operator": ">=",
            "value": 1,
            "note": "continuously and lawfully occupied a Residential Real Property for thirty (30) days"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Transient and tourist hotel occupancy",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "other"
              }
            ]
          }
        },
        {
          "description": "Housing accommodations in a nonprofit hospital, religious facility, extended care facility, or licensed residential care facility",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "other"
              }
            ]
          }
        },
        {
          "description": "Dormitories owned and operated by an educational institution",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "other"
              }
            ]
          }
        },
        {
          "description": "Housing accommodations where tenant shares bathroom or kitchen facilities with owner maintaining principal residence",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Single-family owner-occupied residences renting no more than two units or bedrooms, including ADUs",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "single_family"
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Duplex where owner occupied one unit as principal residence at start and continues in occupancy",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "duplex"
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Housing issued a certificate of occupancy within the previous 15 years",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "building_age_years",
                "operator": "<",
                "value": 15
              }
            ]
          }
        },
        {
          "description": "Alienably separate residential property (e.g. single-family or condo) not owned by a REIT, corporation, or corporate-member LLC, with required notice",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "in",
                "value": [
                  "single_family",
                  "condominium"
                ]
              },
              {
                "field": "owner_type",
                "operator": "not_in",
                "value": [
                  "reit",
                  "corporation"
                ]
              }
            ]
          }
        },
        {
          "description": "Deed-restricted affordable housing or government subsidized housing",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true
              }
            ]
          }
        }
      ],
      "effective_date": "2022-10-18",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "yields_to",
        "target_scope": "state",
        "source_language": "The provisions of this section related to the termination of Tenants shall not apply to Mobilehomes or Mobilehome Spaces in Mobilehome Parks subject to the termination provisions of the Mobilehome Residency Law, Civil Code section 798.56, as applicable."
      },
      "penalty": "Notice rendered void; failure to comply is a complete affirmative defense in an unlawful detainer action; civil action for damages for wrongful eviction with costs and reasonable attorneys' fees.",
      "source_citation": "Santa Ana Mun. Code § 8-3120",
      "quote": {
        "chunk": "c13",
        "start_words": "After a Tenant has continuously and lawfully",
        "end_words": "stated in the written notice to terminate Tenancy."
      },
      "confidence": 0.95
    },
    {
      "category": "rent_increase_limit",
      "title": "Annual Rent Increase Limit",
      "requirement": "Rent increases are capped at 3% or 80% of the change in CPI (whichever is less) and are restricted to no more than one rent increase in any 12-month period. If the change in CPI is negative, no rent increase is permitted.",
      "requirement_es": "Los aumentos de alquiler tienen un límite del 3% o el 80% de la variación del IPC (lo que sea menor) y no se permite más de un aumento en cualquier período de 12 meses. Si la variación del IPC es negativa, no se permite ningún aumento de alquiler.",
      "key_value": {
        "label": "annual rent cap",
        "value": "lesser of 3% or 80% of CPI"
      },
      "coverage_conditions": {
        "type": "AND",
        "clauses": [
          {
            "field": "certificate_of_occupancy_date",
            "operator": "<=",
            "value": "1995-02-01",
            "note": "Pursuant to Costa-Hawkins, exempts property with certificate of occupancy issued after February 1, 1995"
          },
          {
            "field": "building_age_years",
            "operator": ">=",
            "value": 15,
            "note": "Exempts housing issued a certificate of occupancy within the previous 15 years"
          }
        ]
      },
      "exemptions": [
        {
          "description": "Residential Real Property with a certificate of occupancy issued after February 1, 1995 under Costa-Hawkins",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "certificate_of_occupancy_date",
                "operator": ">",
                "value": "1995-02-01"
              }
            ]
          }
        },
        {
          "description": "Housing issued a certificate of occupancy within the previous 15 years",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "building_age_years",
                "operator": "<",
                "value": 15
              }
            ]
          }
        },
        {
          "description": "Deed-restricted affordable housing or government subsidized housing",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Dormitories owned and operated by an educational institution",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "other"
              }
            ]
          }
        },
        {
          "description": "Alienably separate dwelling units (single-family, condo) not owned by a REIT, corporation, or corporate-member LLC, where proper notice has been provided",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "in",
                "value": [
                  "single_family",
                  "condominium"
                ]
              },
              {
                "field": "owner_type",
                "operator": "not_in",
                "value": [
                  "reit",
                  "corporation"
                ]
              }
            ]
          }
        },
        {
          "description": "Two separate dwelling units within a single structure (duplex) where owner occupied one unit at commencement and continues in occupancy",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "duplex"
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true
              }
            ]
          }
        },
        {
          "description": "Mobilehome Space subject to long-term lease, constructed on/after Jan 1 1990, or not used as primary residence",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "==",
                "value": "mobile_home"
              }
            ]
          }
        }
      ],
      "effective_date": "2022-10-18",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "yields_to",
        "target_scope": "state",
        "source_language": "unless expressly exempt under the Costa-Hawkins Rental Housing Act codified in California Civil Code section 1954.50, et seq., or the Mobilehome Residency Law codified in California Civil Code sections 798, et seq."
      },
      "penalty": "Rent increase is ineffective; administrative citation; civil action for damages and injunctive relief; complete affirmative defense in an unlawful detainer action.",
      "source_citation": "Santa Ana Mun. Code § 8-3140",
      "quote": {
        "chunk": "c50",
        "start_words": "Increases in Rent on Residential Real Property",
        "end_words": "in any twelve (12) month period, are prohibited,"
      },
      "confidence": 0.95
    }
  ]
}
